using MediatR;using OAS.Application.Sales.Abstractions;using OAS.Application.Sales.SalesInvoices.Specifications;using OAS.Application.Sales.Services;using OAS.Contracts.Common.Pagination;using OAS.Contracts.Sales.SalesInvoices;
namespace OAS.Application.Sales.SalesInvoices.Queries;
public sealed class GetSalesInvoicesQueryHandler(ISalesInvoiceAggregateRepository repository,SalesInvoiceSpecificationFactory specs,SalesDtoAssembler assembler):IRequestHandler<GetSalesInvoicesQuery,PagedResult<SalesInvoiceDto>>{public async Task<PagedResult<SalesInvoiceDto>> Handle(GetSalesInvoicesQuery r,CancellationToken ct){var n=r.Request.Normalize();var page=await repository.GetPageAsync(specs.CreatePageSpecification(n),ct);var items=new List<SalesInvoiceDto>(page.Items.Count);foreach(var item in page.Items){var full=await repository.GetAggregateAsync(item.Id,false,ct)??item;items.Add(await assembler.InvoiceAsync(full,ct));}return new(){Items=items,PageNumber=n.PageNumber,PageSize=n.PageSize,TotalCount=page.TotalCount};}}
